/* Priority by interactivity (cmux-tui/crates/cmux-app-ffi, src/interactivity.rs): note what the person touches and
 * read the QoS of a class of work. cmux_interactivity_abi_version() returns ABI_VERSION. */

#ifndef CMUX_INTERACTIVITY_H
#define CMUX_INTERACTIVITY_H

/* Generated by cbindgen (cmux-tui/crates/cmux-app-ffi/cbindgen-interactivity.toml); do not edit.
 * Regenerate: CMUX_APP_FFI_HEADER_BLESS=1 cargo test --test interactivity_header (cmux-app-ffi) */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 The ABI version of this header.
 */
uint32_t cmux_interactivity_abi_version(void);

/*
 The person did `kind` now: 0 drag, 1 typing, 2 scroll, 3 focus. An unknown kind changes nothing. Cheap (one atomic
 store): call it on every event of the gesture; the kind stays active for 300-500 ms after the last call.
 */
void cmux_interactivity_note(uint32_t kind);

/*
 Whether the person is interacting now (a noted kind is within its decay).
 */
bool cmux_interactivity_is_interacting(void);

/*
 The QoS for a class of work right now, as a macOS `qos_class_t` raw value (0x21 user-interactive, 0x19
 user-initiated, 0x15 default, 0x11 utility, 0x09 background), or -1 for an unknown class. Classes: 0 input,
 1 frame, 2 focused pane, 3 visible pane, 4 background pane, 5 agent output parse, 6 index, 7 sync, 8 maintenance.
 */
int32_t cmux_interactivity_qos(uint32_t class_);

#endif  /* CMUX_INTERACTIVITY_H */
